def public_healthcheck(root):
 # Execute the exact existing public engine's Python heredoc; do not rewrite workflows.
 s=(root/'.github/workflows/00-bubbleverse-model-start-public.yml').read_text().splitlines()
 start=next(i+1 for i,l in enumerate(s) if l.strip()=="python - <<'PY'")
 end=next(i for i in range(start,len(s)) if s[i].strip()=='PY')
 code='\n'.join(l[10:] for l in s[start:end])+'\n'
 env=dict(os.environ,BV_OPERATION='test',BV_INPUT='')
 result=subprocess.run([sys.executable,'-c',code],cwd=root,env=env,text=True,capture_output=True)
 output=load(root,'run-output/result.json') if (root/'run-output/result.json').is_file() else {}
 if result.returncode or output.get('all_green') is not True:raise RuntimeError('Public healthcheck failed\n'+result.stdout[-5000:]+'\n'+result.stderr[-5000:]+'\n'+json.dumps(output)[-15000:])
 return output

def verify_projected(root):
 q=guard(root,False)
 formal=run(root,[sys.executable,'tests/programs/formal_model_validate.py'])
 campaign=run(root,[sys.executable,'tests/programs/model_campaign.py','validate'])
 before={p.relative_to(root).as_posix():digest(p) for name in ['accepted','model','versions','release','candidate','evidence'] for p in (root/name).rglob('*') if p.is_file()}
 public=public_healthcheck(root)
 after={p.relative_to(root).as_posix():digest(p) for name in ['accepted','model','versions','release','candidate','evidence'] for p in (root/name).rglob('*') if p.is_file()}
 if before!=after:raise RuntimeError('The test healthcheck mutated scientific state')
 suite=run(root,[sys.executable,'-m','unittest','discover','-s','tests/programs','-p','test_*.py'])
 return {'q047':q,'formal_stdout':formal.stdout,'campaign_stdout':campaign.stdout,'public_healthcheck':public,'public_healthcheck_scientific_mutation':False,'unittest_stdout':suite.stdout,'unittest_stderr':suite.stderr}

def main():
 ap=argparse.ArgumentParser();group=ap.add_mutually_exclusive_group(required=True);group.add_argument('--dry-run',action='store_true');group.add_argument('--apply',action='store_true');ap.add_argument('--root',type=Path,default=Path.cwd());args=ap.parse_args();root=args.root.resolve()
 payload_verify()
 if os.environ.get('GITHUB_REPOSITORY') not in [None,TARGET_REPO]:raise RuntimeError('Wrong GitHub repository')
 remote=run(root,['git','remote','get-url','origin']).stdout.strip()
 if not remote.lower().rstrip('/').removesuffix('.git').endswith('morfindien/bubbleverse-model'):raise RuntimeError('Wrong target repository remote')
 run(root,['git','cat-file','-e',BASE+'^{commit}'])
 head=run(root,['git','rev-parse','HEAD']).stdout.strip()
 before_state=load(root,'accepted/model_state.json')
 if before_state.get('current_q')=='Q047':
  result=verify_projected(root);print('ALREADY_CURRENT: Q047/v0.9 verified; no model mutation.');return
 if before_state.get('current_q')!='Q046' or before_state.get('accepted_model_version')!='v0.8' or before_state.get('model_revision')!='R000008':raise RuntimeError('Q sequence/input gate requires Q046/v0.8/R000008')
 expected=json.loads(PAYLOAD['candidate/Q047_PROVENANCE.json'])['protected_input_hashes']
 for rel,sha in expected.items():
  if not (root/rel).is_file() or digest(root/rel)!=sha:raise RuntimeError('Protected baseline differs: '+rel)
 if args.apply and run(root,['git','status','--porcelain']).stdout.strip():raise RuntimeError('Apply requires a clean checkout; commit the uploaded installer/workflow first')
 with tempfile.TemporaryDirectory(prefix='q047-projection-') as temp:
  projected=Path(temp)/'model';copyrepo(root,projected)
  candidate_validation=stage(projected)
  promote_projection(projected,head)
  checks=verify_projected(projected)
  put(projected,'tests/results/Q047_CANDIDATE_VALIDATION.json',candidate_validation)
  put(projected,'tests/results/Q047_PROJECTED_VALIDATION.json',checks)
  put(projected,'provenance/Q047_INSTALLATION_RECEIPT.json',{'target_q':'Q047','status':'PROMOTION_VALIDATED_BEFORE_COMMIT','accepted_before':'v0.8','accepted_after':'v0.9','campaign_input_commit':head,'input_model_commit':BASE,'payload_sha256':PAYLOAD_SHA256,'promotion_commit':None,'promotion_commit_semantics':'Recorded externally by Git history after successful CI commit; no self-referential fabricated SHA.','scientific_result':'INCONCLUSIVE / INSUFFICIENT_EVIDENCE','source_canonical_case_id':None,'source_canonical_result_id':None,'physical_reference_qualified':False,'production_restart_authorized':False,'all_applicable_gates_passed':True,'created_at':datetime.now(timezone.utc).isoformat()})
  changes={}
  for p in projected.rglob('*'):
   if not p.is_file():continue
   rel=p.relative_to(projected).as_posix()
   if rel=='.git' or rel.startswith(('run-output/','__pycache__/','.pytest_cache/','.github/')) or '/__pycache__/' in rel:continue
   if not (root/rel).is_file() or p.read_bytes()!=(root/rel).read_bytes():changes[rel]=p.read_bytes()
  if args.dry_run:
   out=root/'run-output/Q047_DRY_RUN_RESULT.json';put(root,str(out.relative_to(root)),{'status':'PASS_PROJECTED_PROMOTION','target_q':'Q047','candidate_validation':candidate_validation,'projected_validation':checks,'changed_paths':sorted(changes),'accepted_checkout_unchanged':True,'payload_sha256':PAYLOAD_SHA256})
   print('DRY_RUN=PASS; accepted checkout stays Q046/v0.8; projected Q047/v0.9 fully validated.');return
  originals={rel:(root/rel).read_bytes() if (root/rel).exists() else None for rel in changes}
  try:
   # Install staged files first; prove accepted state is unchanged before promotion.
   for rel in PAYLOAD:text(root,rel,PAYLOAD[rel])
   guard(root,True)
   for rel,data in changes.items():
    p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
   final=guard(root,False);run(root,[sys.executable,'tests/programs/model_campaign.py','validate']);public=public_healthcheck(root)
   if not final['all_green'] or not public['all_green']:raise RuntimeError('Post-install validation failed')
  except BaseException:
   for rel,data in originals.items():
    p=root/rel
    if data is None:p.unlink(missing_ok=True)
    else:p.write_bytes(data)
   raise
  put(root,'run-output/Q047_CHANGED_PATHS.json',sorted(changes))
  print('APPLY=PASS; Q047/v0.9 model files installed after validated candidate promotion. Git commit and remote verification still required.')

